export function createAIProvider(): AIProvider {
  if (process.env.SOCIAFLUX_AI_PROVIDER === "openai" && process.env.SOCIAFLUX_OPENAI_API_KEY) {
    return new OpenAIProvider();
  }

  return new MockAIProvider();
}

class MockAIProvider implements AIProvider {
  async analyzeBusiness(scrape: ScrapeResult): Promise<BusinessProfile> {
    const host = safeHost(scrape.sourceUrl);
    const businessName = cleanBusinessName(scrape.title || host);
    const text = [scrape.title, scrape.description, scrape.headings.join(". "), scrape.textSample].filter(Boolean).join(". ");
    const taxonomy = inferBusinessTaxonomy({ title: scrape.title, description: scrape.description, headings: scrape.headings, textSample: scrape.textSample, links: scrape.links });
    const terms = topTerms(text);
    const products = inferProducts(scrape, taxonomy);
    const importantPages = scrape.links.filter((link) => !link.includes("#")).slice(0, 12);
    const country = inferCountry(text, scrape.sourceUrl);
    const languages = inferLanguages(text);
    const primaryValueProposition = inferValueProposition(scrape, taxonomy);
    const dataQualityNote = scrape.status === "complete" ? "public website data" : "limited public website data";

    return {
      businessName,
      website: scrape.sourceUrl,
      logoUrl: scrape.images[0],
      description: scrape.description || firstMeaningfulSentence(text) || `${businessName} has limited public website copy available.`,
      industry: taxonomy.industry,
      category: taxonomy.category,
      products,
      services: taxonomy.services,
      targetAudience: taxonomy.audience,
      brandTone: taxonomy.tone,
      pricePositioning: taxonomy.positioning,
      country,
      languages,
      socialLinks: scrape.socialLinks,
      visualStyle: taxonomy.visualStyle,
      keywords: unique([...terms, taxonomy.category.toLowerCase(), taxonomy.industry.toLowerCase()]).slice(0, 14),
      primaryValueProposition,
      uniqueSellingPoints: inferSellingPoints(text, products, taxonomy),
      brandPersonality: taxonomy.personality,
      estimatedCustomerPersona: inferCustomerPersona(taxonomy, country),
      importantPages,
      contactInformation: scrape.contactHints,
      frequentlyMentionedTerms: terms,
      summary: buildBusinessSummary(businessName, taxonomy, primaryValueProposition, dataQualityNote),
      embeddingText: cleanText([businessName, taxonomy.industry, taxonomy.category, scrape.description, products.join(" "), taxonomy.services.join(" "), terms.join(" ")].join(" ")),
      rawData: scrape
    };
  }

  async analyzeCreator(scrape: ScrapeResult): Promise<CreatorProfile> {
    const text = [scrape.title, scrape.description, scrape.headings.join(". "), scrape.textSample].filter(Boolean).join(". ");
    const handle = extractCreatorHandle(scrape) || "@creator";
    const name = extractCreatorName(scrape, handle);
    const bio = extractCreatorBio(scrape);
    const intelligence = inferCreatorIntelligence(text);
    const followerCount = parseMetric(text, "Followers");
    const followingCount = parseMetric(text, "Following");
    const postCount = parseMetric(text, "Posts");
    const publicDataLimited = scrape.status !== "complete";

    return {
      name,
      handle,
      bio,
      website: scrape.links.find((link) => !link.includes("instagram.com")),
      profileImage: scrape.images[0] || "",
      publicFollowerCount: followerCount,
      publicFollowingCount: followingCount,
      publicPostCount: postCount,
      primaryNiche: intelligence.primaryNiche,
      secondaryNiches: intelligence.secondaryNiches,
      topicsDiscussed: intelligence.topics,
      contentPillars: intelligence.contentPillars,
      contentStyles: intelligence.contentStyles,
      brandPersonality: intelligence.brandPersonality,
      estimatedAudience: intelligence.estimatedAudience,
      contentQuality: {
        imageQuality: publicDataLimited ? "Needs visual review" : "AI estimate from public profile only",
        videoQuality: publicDataLimited ? "Needs visual review" : "AI estimate from public profile only",
        editingQuality: publicDataLimited ? "Needs review" : intelligence.editingQuality,
        brandingConsistency: intelligence.brandingConsistency,
        postingConsistency: postCount && followerCount ? "Visible public activity" : "Needs review"
      },
      postingBehaviour: {
        approximateFrequency: postCount ? "Public post count visible; frequency needs recent-post review" : "Unknown from public metadata",
        dominantFormat: intelligence.dominantFormat,
        captionStyle: intelligence.captionStyle,
        hashtagUsage: bio.includes("#") ? "Hashtags visible in bio" : "No public hashtag signal in bio"
      },
      brandSafety: {
        profanityRisk: containsAny(text, ["fuck", "shit", "nsfw"]) ? "Medium" : "Low from public bio",
        politicalContent: containsAny(text, ["politics", "election", "government", "activist"]) ? "Possible" : "None detected in public bio",
        sensitiveTopics: containsAny(text, ["adult", "betting", "crypto", "gambling"]) ? "Possible" : "Low from public bio",
        adultContentIndicators: containsAny(text, ["18+", "onlyfans", "nsfw"]) ? "Possible" : "None detected in public bio",
        overallScore: containsAny(text, ["18+", "onlyfans", "nsfw", "gambling"]) ? 68 : 86
      },
      previousCollaborations: {
        detectedSponsoredContent: containsAny(text, ["ad", "sponsored", "partner", "collab"]) ? ["Public bio suggests partnership or collaboration language"] : [],
        mentionedBrands: extractMentionedBrands(text),
        productCategories: intelligence.productCategories
      },
      pricing: estimateCreatorPricing(followerCount),
      summary: buildCreatorSummary(name, handle, intelligence, publicDataLimited),
      embeddingText: cleanText([handle, name, bio, intelligence.primaryNiche, intelligence.topics.join(" "), intelligence.contentStyles.join(" ")].join(" ")),
      rawData: scrape
    };
  }
  async matchBusinessToCreator(business: BusinessProfile, creator: CreatorProfile, budget?: number) {
    return computeMatch(business, creator, budget);
  }
}

class OpenAIProvider extends MockAIProvider {
  private readonly client = new OpenAI({ apiKey: process.env.SOCIAFLUX_OPENAI_API_KEY });
  private readonly model = process.env.SOCIAFLUX_OPENAI_MODEL || "gpt-4o-mini";

  async analyzeBusiness(scrape: ScrapeResult): Promise<BusinessProfile> {
    const fallback = await super.analyzeBusiness(scrape);
    const parsed = await this.completeJson<Partial<BusinessProfile>>(businessProfilePrompt, { scrape, fallback }, fallback);
    return normalizeBusinessProfile({ ...fallback, ...parsed, rawData: scrape }, fallback);
  }

  async analyzeCreator(scrape: ScrapeResult): Promise<CreatorProfile> {
    const text = [scrape.title, scrape.description, scrape.headings.join(". "), scrape.textSample].filter(Boolean).join(". ");
    const handle = extractCreatorHandle(scrape) || "@creator";
    const name = extractCreatorName(scrape, handle);
    const bio = extractCreatorBio(scrape);
    const intelligence = inferCreatorIntelligence(text);
    const followerCount = parseMetric(text, "Followers");
    const followingCount = parseMetric(text, "Following");
    const postCount = parseMetric(text, "Posts");
    const publicDataLimited = scrape.status !== "complete";

    return {
      name,
      handle,
      bio,
      website: scrape.links.find((link) => !link.includes("instagram.com")),
      profileImage: scrape.images[0] || "",
      publicFollowerCount: followerCount,
      publicFollowingCount: followingCount,
      publicPostCount: postCount,
      primaryNiche: intelligence.primaryNiche,
      secondaryNiches: intelligence.secondaryNiches,
      topicsDiscussed: intelligence.topics,
      contentPillars: intelligence.contentPillars,
      contentStyles: intelligence.contentStyles,
      brandPersonality: intelligence.brandPersonality,
      estimatedAudience: intelligence.estimatedAudience,
      contentQuality: {
        imageQuality: publicDataLimited ? "Needs visual review" : "AI estimate from public profile only",
        videoQuality: publicDataLimited ? "Needs visual review" : "AI estimate from public profile only",
        editingQuality: publicDataLimited ? "Needs review" : intelligence.editingQuality,
        brandingConsistency: intelligence.brandingConsistency,
        postingConsistency: postCount && followerCount ? "Visible public activity" : "Needs review"
      },
      postingBehaviour: {
        approximateFrequency: postCount ? "Public post count visible; frequency needs recent-post review" : "Unknown from public metadata",
        dominantFormat: intelligence.dominantFormat,
        captionStyle: intelligence.captionStyle,
        hashtagUsage: bio.includes("#") ? "Hashtags visible in bio" : "No public hashtag signal in bio"
      },
      brandSafety: {
        profanityRisk: containsAny(text, ["fuck", "shit", "nsfw"]) ? "Medium" : "Low from public bio",
        politicalContent: containsAny(text, ["politics", "election", "government", "activist"]) ? "Possible" : "None detected in public bio",
        sensitiveTopics: containsAny(text, ["adult", "betting", "crypto", "gambling"]) ? "Possible" : "Low from public bio",
        adultContentIndicators: containsAny(text, ["18+", "onlyfans", "nsfw"]) ? "Possible" : "None detected in public bio",
        overallScore: containsAny(text, ["18+", "onlyfans", "nsfw", "gambling"]) ? 68 : 86
      },
      previousCollaborations: {
        detectedSponsoredContent: containsAny(text, ["ad", "sponsored", "partner", "collab"]) ? ["Public bio suggests partnership or collaboration language"] : [],
        mentionedBrands: extractMentionedBrands(text),
        productCategories: intelligence.productCategories
      },
      pricing: estimateCreatorPricing(followerCount),
      summary: buildCreatorSummary(name, handle, intelligence, publicDataLimited),
      embeddingText: cleanText([handle, name, bio, intelligence.primaryNiche, intelligence.topics.join(" "), intelligence.contentStyles.join(" ")].join(" ")),
      rawData: scrape
    };
  }
  async matchBusinessToCreator(business: BusinessProfile, creator: CreatorProfile, budget?: number) {
    const fallback = await super.matchBusinessToCreator(business, creator, budget);
    return this.completeJson<MatchResult>(matchingPrompt, { business, creator, budget }, fallback);
  }

  private async completeJson<T>(system: string, payload: unknown, fallback: T): Promise<T> {
    try {
      const response = await this.client.chat.completions.create({
        model: this.model,
        temperature: 0.2,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: system },
          { role: "user", content: JSON.stringify(payload) }
        ]
      });

      const content = response.choices[0]?.message.content;
      return content ? ({ ...fallback, ...JSON.parse(content) } as T) : fallback;
    } catch {
      return fallback;
    }
  }
}


function inferProducts(scrape: ScrapeResult, taxonomy: BusinessTaxonomy) {
  // Products named on the page beat the category defaults, which are only a fallback.
  return unique([...extractProducts(scrape), ...taxonomy.products]).slice(0, 12);
}

function extractProducts(scrape: ScrapeResult) {
  const fromHeadings = scrape.headings.filter((heading) => isProductLike(heading));
  const fromLinks = scrape.links
    .filter((link) => /\/products\/|\/collections\//i.test(link))
    .map((link) => decodeURIComponent(link.split("/").filter(Boolean).pop() || ""))
    .map((slug) => slug.replace(/[-_]+/g, " "))
    .map(titleCase)
    .filter((value) => value.length > 3 && !/^Featured Collections$/i.test(value));

  return unique([...fromHeadings, ...fromLinks]);
}

function inferValueProposition(scrape: ScrapeResult, taxonomy: BusinessTaxonomy) {
  if (scrape.description && !/built on replit|update this description/i.test(scrape.description)) {
    return firstMeaningfulSentence(scrape.description) || scrape.description;
  }

  if (taxonomy.category === "AI venture studio") {
    return "A venture studio that helps founders build, launch, and scale AI-first and enterprise-grade businesses.";
  }

  if (taxonomy.category === "Art stationery") {
    return "Art papers, sketchbooks, journals, and canvas products for artists across skill levels and media.";
  }

  return `A ${taxonomy.category.toLowerCase()} offering for ${taxonomy.audience.slice(0, 2).join(" and ").toLowerCase()}.`;
}

function inferSellingPoints(text: string, products: string[], taxonomy: BusinessTaxonomy) {
  const lowered = text.toLowerCase();
  const points = new Set<string>();

  if (hasAny(lowered, ["premium", "high quality", "quality"])) points.add("Quality-led positioning");
  if (hasAny(lowered, ["free shipping", "first order", "sale"])) points.add("Active ecommerce offers");
  if (hasAny(lowered, ["community", "events", "cohort"])) points.add("Community or cohort-led engagement");
  if (hasAny(lowered, ["ai-native", "ai first", "ai-first", "automation"])) points.add("AI-native execution focus");
  if (hasAny(lowered, ["investor-ready", "venture capital", "fundraising"])) points.add("Fundraising and venture readiness support");

  products.slice(0, 3).forEach((product) => points.add(product));
  taxonomy.services.slice(0, 2).forEach((service) => points.add(service));

  return Array.from(points).slice(0, 8);
}

function inferCustomerPersona(taxonomy: BusinessTaxonomy, country: string) {
  if (taxonomy.category === "Art stationery") {
    return [`${country} artists buying supplies online`, "Students exploring art media", "Hobbyists and professionals comparing paper formats"];
  }

  if (taxonomy.category === "AI venture studio") {
    return ["Experienced founders with strong domain insight", "Startup teams preparing for venture-scale growth", "Executives building AI-first businesses"];
  }

  return taxonomy.audience.map((audience) => `${audience} interested in ${taxonomy.category.toLowerCase()}`);
}

function buildBusinessSummary(name: string, taxonomy: BusinessTaxonomy, valueProposition: string, dataQualityNote: string) {
  return `${name} is profiled as ${articleFor(taxonomy.category)} ${formatCategory(taxonomy.category)} business in ${taxonomy.industry.toLowerCase()}, based on ${dataQualityNote}. ${valueProposition} Best-fit creators should speak to ${taxonomy.audience.slice(0, 3).join(", ").toLowerCase()} using ${taxonomy.tone.join(", ").toLowerCase()} creator tone.`;
}

function topTerms(text: string) {
  const counts = cleanText(text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((word) => word.length > 3 && !genericStopWords.has(word) && !/^\d+$/.test(word))
    .reduce<Record<string, number>>((accumulator, word) => {
      accumulator[word] = (accumulator[word] || 0) + 1;
      return accumulator;
    }, {});

  return Object.entries(counts)
    .sort((left, right) => right[1] - left[1])
    .slice(0, 14)
    .map(([word]) => word);
}

function inferCountry(text: string, sourceUrl: string) {
  const lowered = text.toLowerCase();
  if (lowered.includes("india") || lowered.includes("inr") || sourceUrl.endsWith(".in")) return "India";
  if (lowered.includes("united states") || lowered.includes("usa") || lowered.includes("usd")) return "United States";
  if (lowered.includes("united kingdom") || lowered.includes("gbp")) return "United Kingdom";
  return "AI estimate: unknown";
}

function inferLanguages(text: string) {
  if (/\b(hindi|marathi|tamil|telugu|kannada|bengali)\b/i.test(text)) return ["English", "AI estimate: Indian regional languages"];
  return ["English"];
}

function normalizeBusinessProfile(profile: BusinessProfile, fallback: BusinessProfile): BusinessProfile {
  const badDemoCategory = profile.category === "Skincare" && fallback.category !== "Skincare";
  return badDemoCategory
    ? {
        ...profile,
        industry: fallback.industry,
        category: fallback.category,
        products: fallback.products,
        services: fallback.services,
        targetAudience: fallback.targetAudience,
        brandTone: fallback.brandTone,
        pricePositioning: fallback.pricePositioning,
        visualStyle: fallback.visualStyle,
        primaryValueProposition: fallback.primaryValueProposition,
        uniqueSellingPoints: fallback.uniqueSellingPoints,
        brandPersonality: fallback.brandPersonality,
        estimatedCustomerPersona: fallback.estimatedCustomerPersona,
        summary: fallback.summary
      }
    : profile;
}

function extractCreatorHandle(scrape: ScrapeResult) {
  const text = [scrape.title, scrape.textSample, scrape.sourceUrl].join(" ");
  const handleMatch = text.match(/@([a-zA-Z0-9._]+)/) || scrape.sourceUrl.match(/instagram\.com\/([a-zA-Z0-9._]+)/);
  return handleMatch ? `@${handleMatch[1].toLowerCase()}` : undefined;
}

function extractCreatorName(scrape: ScrapeResult, handle: string) {
  const title = cleanText(scrape.title || "");
  const titleMatch = title.match(/^(.+?)\s*\(@/);
  if (titleMatch?.[1]) return titleMatch[1];
  const nameMatch = scrape.textSample.match(/Name:\s*([^\.]+)/i);
  if (nameMatch?.[1]) return cleanText(nameMatch[1]);
  return title && !title.startsWith("@") ? title : handle.replace("@", "").replace(/[._-]/g, " ");
}

function extractCreatorBio(scrape: ScrapeResult) {
  const bioMatch = scrape.textSample.match(/Bio:\s*(.+?)(?:\. Followers:|\. Following:|\. Posts:|$)/i);
  const instagramDescriptionBio = scrape.description?.match(/on Instagram:\s*["â€œ](.*?)["â€]?$/i)?.[1];
  const bio = cleanText(bioMatch?.[1] || instagramDescriptionBio || "").replace(/^"+|"+$/g, "").trim();
  if (!bio || /limited public instagram information|instagram public profile retrieval/i.test(bio)) {
    return "Public profile bio was not available. Creator should confirm bio manually.";
  }
  return bio;
}

