    return creatorIntelligence("Fashion", ["Lifestyle", "Shopping", "Personal style"], ["Outfits", "Styling", "Product recommendations"], ["Outfit posts", "Hauls", "Style guides"], ["Lifestyle", "Reviews", "Personal branding"], ["Bold", "Aspirational", "Stylish"], ["Fashion", "Accessories", "Beauty"], "Visual and trend-led", "Needs visual confirmation", "Reels and static posts", "Short and style-led", ["18-34"], ["Fashion", "Shopping", "Trends"], ["AI estimate: urban style audience"], ["English"]);
