function firstMeaningfulSentence(value: string) {
  return cleanText(value)
    .split(/(?<=[.!?])\s+/)
    .find((sentence) => sentence.length > 24 && !/built on replit|update this description/i.test(sentence));
}

function isProductLike(value: string) {
  return /paper|sketch|journal|canvas|book|pad|kit|panel|software|platform|lab|scale|build|portfolio|venture/i.test(value);
}

function titleCase(value: string) {
  return value.replace(/\b\w/g, (character) => character.toUpperCase()).trim();
}

function cleanText(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

function unique<T>(values: T[]) {
  return Array.from(new Set(values.filter(Boolean)));
}











